\copy (SELECT p.code AS proj, d.unit_number AS unit, sc.id AS contract_id, sc.sale_price, coalesce(sc.total_paid,0) AS total_paid, (SELECT max(i.payment_date) FROM sale_contract_installment i WHERE i.contract_id=sc.id AND i.state='paid') AS last_pay, sc.contract_date FROM sale_contract sc JOIN property_details d ON d.id=sc.property_id JOIN property_project p ON p.id=d.project_id ORDER BY p.code, d.unit_number) TO '/tmp/dash_contracts.csv' WITH CSV HEADER
